// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz: from (as address), v (amount), and a single recipient addr
    // The reference contract should always return true (i.e., transfer completes)
    // for any non-empty _tos array; the mutant that passes v+1 may fail when
    // the callee expects exactly v. We therefore deploy a helper token that
    // enforces exact amount matching and will revert otherwise. This helper
    // models the external contract called via low-level call.
    function testFuzz_property(address from, uint256 v, address to) public {
        // Keep admissible domains: non-zero to and from (avoid zero-address trivialities)
        vm.assume(to != address(0));
        vm.assume(from != address(0));
        // Build recipients array with single entry `to`
        address[] memory tos = new address[](1);
        tos[0] = to;

        // Deploy helper that expects the amount passed to transferFrom to equal v
        ExactAmountReceiver helper = new ExactAmountReceiver(v);

        // Now call c.transfer(from, address(helper), tos, v) as an EOA (no value transfer)
        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always invokes the callee with the exact v
        // so when the callee enforces equality it will succeed; therefore ok must be true
        assertTrue(ok);
    }
}

// Adversarial helper: expects transferFrom(from, to, amount) where amount must equal the provided expectedAmount
contract ExactAmountReceiver {
    uint256 public expected;
    constructor(uint256 _expected) { expected = _expected; }

    // Minimal function matching selector transferFrom(address,address,uint256)
    function transferFrom(address /*from*/, address /*to*/, uint256 amount) external returns (bool) {
        require(amount == expected, "bad amount");
        return true;
    }
}

