pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address, value v, and a single recipient in _tos (we pass array of length 1)
    function testFuzz_property(address from, uint256 v) public {
        // Keep from non-zero to be a sensible address, leave v wide
        vm.assume(from != address(0));

        // Deploy a helper that always succeeds on transferFrom (so low-level call returns true)
        SuccessCallee okC = new SuccessCallee();

        // prepare tos array with one element (fuzzer supplies 'from' and 'v', we use from as recipient to vary behavior)
        address[] memory tos = new address[](1);
        tos[0] = from;

        // Call c.transfer; reference should NOT revert because the callee returns success and reference requires _s
        bool ok;
        try c.transfer(from, address(okC), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any admissible inputs (non-empty _tos and a callee that returns success),
        // the reference contract completes (ok == true). The mutant that inverts the check will revert
        // when the callee call succeeds; therefore asserting ok == true distinguishes them.
        assertTrue(ok);
    }
}

// Adversarial helper: always returns true for transferFrom(address,address,uint256)
contract SuccessCallee {
    // match selector transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // fallback to accept generic low-level calls that encode that selector
    fallback() external payable {
        // if called via low-level call with selector, do nothing (succeed)
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: from (actor) and v (value) and a boolean to choose whether to include at least one tos
    function testFuzz_property(address from, uint256 v, bool includeTos) public {
        // Keep domain wide but sensible: require non-zero address for from and at least one tos when includeTos
        vm.assume(from != address(0));

        // Deploy an adversarial callee that always reverts on the expected selector
        Reverter reverter = new Reverter();

        // Build tos array: if includeTos is false, make it empty (should revert due to require(_tos.length>0));
        // if includeTos is true, include one address (any address) that will cause the callee to be invoked and revert.
        address[] memory tos;
        if (includeTos) {
            tos = new address[](1);
            tos[0] = address(0x1234); // the specific value here is irrelevant; the callee is separate
        } else {
            tos = new address[](0);
        }

        // We will call c.transfer(from, address(reverter), tos, v) and observe whether it reverts.
        // According to the reference contract, if tos.length == 0 it must revert (require). If tos.length>0,
        // the reference will invoke external calls and require each succeed; because reverter reverts those calls,
        // the reference should revert. The mutant that ignores the call return value will not revert for the failing
        // internal low-level call and therefore may return true when the reference reverts.

        bool ok;
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): For all admissible inputs, the reference contract never returns true when
        // the callee reverts during a transferFrom call. We observe this by calling the reference c and asserting
        // that the call did NOT succeed (ok == false) whenever tos.length > 0 (because reverter always reverts its calls).
        // This assertion holds for the correct reference implementation for all fuzz inputs, and the mutant that
        // ignores sub-call failures will violate it for some inputs (it may return true while sub-call reverted).
        if (includeTos) {
            assertTrue(ok == false);
        } else {
            // when tos is empty the contract must revert due to require(_tos.length > 0);
            assertTrue(ok == false);
        }
    }
}

// Adversarial helper: always revert on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an arbitrary from address and an array length selector (as uint) and a value
    // we cannot fuzz an address to be a contract with code, so we deploy a helper contract that implements
    // transferFrom but NOT transfer. We still fuzz the from address and the value.
    function testFuzz_property(address from, uint256 v, uint256 tosLen) public {
        // keep tosLen reasonable but allow zero to be rejected by require; we want >0
        uint256 len = bound(tosLen, 1, 8);

        // deploy helper that implements transferFrom(...) but NOT transfer(...)
        CalleeImplementsTransferFrom helper = new CalleeImplementsTransferFrom();

        // build an array of receiver addresses (use this contract's address for all entries)
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = address(this);

        // call c.transfer which will low-level call helper with selector for transferFrom in the reference
        // we pass helper's address as caddress so C will call helper
        bool ok;
        try c.transfer(from, address(helper), tos, uint(v)) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERTION: the reference implementation always succeeds when callee implements transferFrom(...) (for any inputs with tos.length>0);
        // the mutant that invokes transfer(...) would fail because helper does NOT implement transfer(...).
        assertTrue(ok);
    }
}

// Helper that defines transferFrom(address,address,uint256) and returns true, but does NOT define transfer(address,address,uint256)
contract CalleeImplementsTransferFrom {
    // matching signature called by the reference: transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    // no transfer(address,address,uint256) function present
}
